/*---
author: Caitlin Potter <caitp@igalia.com>
esid: sec-async-generator-function-definitions-static-semantics-early-errors
description: >
  It is a syntax error if AsyncGeneratorBody contains SuperCall is true.
negative:
  phase: parse
  type: SyntaxError
features: [async-iteration]
---*/

$DONOTEVALUATE();

(async function*() { super(); });

class B extends A {
    constructor() { super?.(); }
}

class B extends A {
    get prop() { return super?.a; }
}

class aa {
  static accessor a = true;
  accessor b = true;
  accessor #c = true;
}

@(foo().bar)
@(foo()).bar
class Foo {
  @(member[expression]) method() {}

  @(foo + bar) method2() {}

  @(this.foo)(bar) method3() {}

  @(member?.expression) method4() { }
}
